"""Tests for ``POST /v1/inbox-jobs/cancel-batch``.

An atomic batch cancellation of 1:1-inbox redelivery jobs: the body
carries a ``device_id`` and a non-empty ``items`` array of
``job_id``/``cancellation_id`` pairs (both unique across items). Every
item is prechecked in array order with the single-job ``op=cancel``
rules (first error aborts the batch, its ``field`` prefixed to
``items[i].``); only then does the batch cancel in input order and
commit once. A batch whose items all replay their committed
cancellations answers 200 and writes nothing; a partial replay
conflicts 409 with the first replayed item's
``items[i].cancellation_id``.
"""
import json
import os
import shutil
import tempfile
import threading
import unittest
from http.client import HTTPConnection

from tests.test_device_inbox import InboxMixin
from e2ee_backend.persistence import (
    PersistenceUnavailable, attach_persistence)
from e2ee_backend.service import DeviceService, ServiceError
from e2ee_backend.http_app import create_server


_PAST = "2000-01-01T00:00:00.000000+00:00"


class _BatchMixin(InboxMixin):
    def _error(self, callable_):
        with self.assertRaises(ServiceError) as caught:
            callable_()
        return caught.exception

    def _job(self, device_id="bob", job_id="j1", op="queue", **extra):
        payload = {"device_id": device_id, "job_id": job_id, "op": op}
        payload.update(extra)
        return self.service.inbox_job(payload)

    def _dispatch(self, job_id="j1", device_id="bob"):
        self._job(device_id=device_id, job_id=job_id)
        return self._job(device_id=device_id, job_id=job_id, op="dispatch")

    def _expire(self, lease_id: str) -> None:
        with self.service.store._lock:
            for state in self.service.store._delivery.values():
                for lease in state.leases:
                    if lease.lease_id == lease_id:
                        lease.leased_until = _PAST

    def _batch(self, device_id="bob", items=None, **extra):
        payload = {"device_id": device_id,
                   "items": items if items is not None else []}
        payload.update(extra)
        return self.service.inbox_job_cancel_batch(payload)

    def _pending_and_running_jobs(self):
        # jp stays pending; jr dispatches and leases the whole inbox as a
        # running job.
        self._job(job_id="jp")
        self._dispatch(job_id="jr")


